    private static List<(string Reference, decimal Net)> CollectAccepted(
        IEnumerable<PaymentItem> items,
        string settlementCurrency,
        decimal percentageFee,
        decimal fixedFee,
        decimal submissionLimit,
        List<SettlementLine> lines)
    {
        var accepted = new List<(string Reference, decimal Net)>();
        var seen = new HashSet<string>(StringComparer.Ordinal);

        foreach (var item in items)
        {
            var rejectionStatus = GetInitialRejectionStatus(item, settlementCurrency, seen);
            if (rejectionStatus is not null)
            {
                lines.Add(new SettlementLine(item.Reference, 0m, rejectionStatus));
                continue;
            }

            var net = CalculateNet(item.GrossAmount, percentageFee, fixedFee);
            if (net <= 0m)
            {
                lines.Add(new SettlementLine(item.Reference, 0m, "fee-exceeds-amount"));
                continue;
            }

            if (accepted.Sum(entry => entry.Net) + net > submissionLimit)
            {
                lines.Add(new SettlementLine(item.Reference, 0m, "batch-limit"));
                continue;
            }

            accepted.Add((item.Reference, net));
        }

        return accepted;
    }

    private static string? GetInitialRejectionStatus(
        PaymentItem item,
        string settlementCurrency,
        HashSet<string> seen)
    {
        if (string.IsNullOrWhiteSpace(item.Reference))
            return "invalid-reference";
        if (!seen.Add(item.Reference))
            return "duplicate";
        if (!string.Equals(item.Currency, settlementCurrency, StringComparison.OrdinalIgnoreCase))
