            return "invalid-amount";
        if (item.Refunded)
            return "refunded";
        if (item.Held)
            return "held";

        return null;
    }

    private static decimal CalculateNet(decimal grossAmount, decimal percentageFee, decimal fixedFee)
    {
        var fee = decimal.Round(grossAmount * percentageFee + fixedFee, 2);
        return decimal.Round(grossAmount - fee, 2);
    }

    private static SettlementResult CreateRejectedResult(
        List<SettlementLine> lines,
        List<(string Reference, decimal Net)> accepted,
        string status)
    {
        return new SettlementResult(
            [.. lines, .. accepted.Select(entry => new SettlementLine(entry.Reference, 0m, status))],
            0m,
            "rejected");
    }
